{"cards": [{"node_code": "N_4a90ba2fc2720c94", "definition": "研究监督、无监督及强化学习等经典机器学习算法在交通预测、识别、分类及异常检测中的具体应用与模型适配。", "boundary": "本节点聚焦于非大模型、非纯NLP的机器学习算法在交通场景的落地。不包含基于Transformer架构的大模型研究（归入交通大模型）或侧重语义理解的自然语言处理（归入交通自然语言处理）。若算法核心是图神经网络且侧重知识推理，需视是否构建图谱而定，通常纯预测归此，图谱构建归知识图谱。", "includes": ["交通流量预测、事故风险识别及出行模式分类的机器学习模型", "基于随机森林、SVM、XGBoost等算法的交通数据分析应用", "强化学习在交通信号控制或路径规划中的算法研究"], "excludes": ["交通大模型（LLM）的架构设计、预训练及微调技术（归入交通大模型）", "交通知识图谱的本体构建、实体抽取及推理机制（归入交通知识图谱）", "交通文本挖掘、语义分析及对话系统（归入交通自然语言处理）"], "sibling_distinctions": [{"other_code": "N_01bf4415b3cb9420", "rule": "本节点侧重传统或中等规模机器学习算法（如树模型、CNN、RNN）；兄弟节点侧重基于Transformer的大规模预训练模型及其在交通领域的适配。"}, {"other_code": "N_d2696c1f26c8362a", "rule": "本节点侧重数值型数据的预测与分类；兄弟节点侧重结构化知识表示、关系推理及语义网络构建。"}, {"other_code": "N_a73187b9cf4d86a7", "rule": "本节点处理通用交通数据（数值、图像等）；兄弟节点专门处理交通领域的文本、语音等非结构化语言数据。"}], "cross_boundary_rule": "若研究使用图神经网络进行交通流预测，主挂载归入本节点；若研究重点在于构建交通实体关系图谱，主挂载归入交通知识图谱。"}, {"node_code": "N_d2696c1f26c8362a", "definition": "研究交通领域知识图谱的本体设计、实体关系抽取、知识融合、推理及问答系统，旨在实现交通知识的结构化表示与智能应用。", "boundary": "本节点聚焦于“知识”的结构化表示与推理，而非单纯的数值预测或文本处理。不包含通用的机器学习预测算法（归入机器学习交通应用）或大模型的通用能力研究（归入交通大模型）。若内容涉及从交通文本中抽取实体构建图谱，抽取技术可关联NLP，但图谱构建与应用归入本节点。", "includes": ["交通领域本体构建、实体识别及关系抽取技术", "交通知识图谱的存储、查询、推理及补全算法", "基于知识图谱的交通智能问答、推荐及决策支持系统"], "excludes": ["交通流量预测、事故分类等数值型机器学习任务（归入机器学习交通应用）", "交通大模型的预训练、微调及通用生成能力（归入交通大模型）", "纯文本挖掘、情感分析及语义相似度计算（归入交通自然语言处理）"], "sibling_distinctions": [{"other_code": "N_4a90ba2fc2720c94", "rule": "本节点侧重符号化、结构化的知识表示与逻辑推理；兄弟节点侧重基于统计或神经网络的数值预测与模式识别。"}, {"other_code": "N_01bf4415b3cb9420", "rule": "本节点侧重显式的知识结构与推理；兄弟节点侧重隐式的参数化表示与生成能力，大模型可作为图谱构建的工具，但图谱本身归此。"}, {"other_code": "N_a73187b9cf4d86a7", "rule": "本节点利用NLP技术作为手段构建知识；兄弟节点研究NLP算法本身在交通文本处理中的应用，不强调知识结构化。"}], "cross_boundary_rule": "若研究“利用大模型辅助构建交通知识图谱”，主挂载归入本节点（侧重图谱构建）；若研究“大模型在交通问答中的表现”，主挂载归入交通大模型。"}, {"node_code": "N_01bf4415b3cb9420", "definition": "研究基于Transformer等架构的大规模预训练模型在交通领域的适配、微调、提示工程及应用，涵盖交通多模态大模型及生成式AI应用。", "boundary": "本节点聚焦于“大模型”（LLM/Foundation Models）在交通场景的特定应用与优化。不包含传统机器学习算法（归入机器学习交通应用）或专门的知识图谱构建（归入交通知识图谱）。若内容涉及大模型用于交通文本生成或对话，需区分是通用NLP能力还是交通特定大模型，通常交通特定大模型归此，通用NLP算法归NLP。", "includes": ["交通领域大模型的预训练、微调、对齐及提示工程", "交通多模态大模型（文本、图像、视频融合）的研究与应用", "基于大模型的交通智能体、生成式规划及复杂场景理解"], "excludes": ["传统机器学习算法（如SVM、随机森林）及非大模型架构的深度学习（归入机器学习交通应用）", "交通知识图谱的本体设计与推理算法（归入交通知识图谱）", "通用自然语言处理算法研究，非针对交通大模型（归入交通自然语言处理）"], "sibling_distinctions": [{"other_code": "N_4a90ba2fc2720c94", "rule": "本节点侧重参数规模大、具备通用生成或理解能力的大模型；兄弟节点侧重特定任务的传统或中等规模机器学习模型。"}, {"other_code": "N_d2696c1f26c8362a", "rule": "本节点侧重模型本身的参数化表示与生成能力；兄弟节点侧重显式的知识结构与符号推理，大模型可作为图谱构建工具，但图谱归此。"}, {"other_code": "N_a73187b9cf4d86a7", "rule": "本节点侧重交通特定领域的大模型架构与训练；兄弟节点侧重交通文本的NLP算法（如分词、句法分析），不强调大模型特性。"}], "cross_boundary_rule": "若研究“交通大模型在知识图谱构建中的应用”，主挂载归入交通知识图谱（侧重应用目标）；若研究“交通大模型的架构改进”，主挂载归入本节点。"}]}
